from pathlib import Path


def replace_once(path: str, old: str, new: str) -> None:
    p = Path(path)
    text = p.read_text()
    if old not in text:
        raise SystemExit(f"marker not found in {path}: {old[:80]!r}")
    p.write_text(text.replace(old, new, 1))


replace_once(
    "src/graft_plus/semantic.py",
    """                if last not in _ROUTE_METHODS or not path_lit:\n                    continue\n                add_route(\n""",
    """                if last not in _ROUTE_METHODS or not path_lit:\n                    continue\n                owner = name.rsplit(\".\", 1)[0] if \".\" in name else \"\"\n                if not owner or not path_lit.startswith(\"/\"):\n                    continue\n                if owner in {\"mock\", \"unittest.mock\"} or owner.endswith(\".mock\"):\n                    continue\n                add_route(\n""",
)

p = Path("src/graft_plus/completeness.py")
text = p.read_text()
marker = "\n\ndef audit(graph: dict[str, Any], overlay: dict[str, Any] | None = None, impact: dict[str, Any] | None = None, subject: Path | None = None) -> dict[str, Any]:\n"
helper = '''\n\ndef _classify_unresolved_imports(graph: dict[str, Any]) -> dict[str, int]:\n    counts: Counter[str] = Counter()\n    for row in (graph.get("facts") or {}).get("unresolved_imports") or []:\n        specifier = str(row.get("specifier") or "")\n        source = str(row.get("from") or "").lower()\n        lowered = specifier.lower()\n        if lowered.startswith(("http://", "https://", "chrome:", "chrome-untrusted:", "devtools:", "file:")):\n            kind = "url_or_scheme"\n        elif specifier.startswith("."):\n            kind = "relative_internal_reference"\n        elif any(token in source for token in ("/test", "tests/", ".test.", ".spec.", "fixture")):\n            kind = "test_or_fixture_context"\n        elif any(token in source for token in ("generated", "gen/", "out/", "build/")):\n            kind = "generated_or_build_context"\n        elif lowered.startswith(("tools.", "tools/", "build.", "build/", "scripts.", "scripts/")):\n            kind = "tooling_or_build_reference"\n        else:\n            kind = "unresolved_absolute_reference"\n        counts[kind] += 1\n    return dict(sorted(counts.items()))\n'''
if marker not in text:
    raise SystemExit("audit marker missing")
text = text.replace(marker, helper + marker, 1)
text = text.replace(
    '    overlay = overlay or {}\n    impact = impact or {}\n    known = {str(n["id"]) for n in graph["nodes"]}\n',
    '    overlay = overlay or {}\n    impact = impact or {}\n    node_id_counts = Counter(str(node.get("id") or "") for node in graph.get("nodes") or [] if node.get("id"))\n    duplicate_node_ids = sorted(node_id for node_id, count in node_id_counts.items() if count > 1)\n    duplicate_node_occurrences = sum(count - 1 for count in node_id_counts.values() if count > 1)\n    known = {str(n["id"]) for n in graph["nodes"]}\n',
    1,
)
text = text.replace(
    '    integrity_pass = not missing_endpoints and not unacknowledged_blocking and not missing_edge_evidence\n',
    '    integrity_pass = not duplicate_node_ids and not missing_endpoints and not unacknowledged_blocking and not missing_edge_evidence\n',
    1,
)
text = text.replace(
    '        "overlay": "attached" if overlay_nodes else "residual",\n        "unresolved_import_count": len((graph.get("facts") or {}).get("unresolved_imports") or []),\n',
    '        "overlay": "attached" if overlay_nodes else "residual",\n        "identity_collision_count": duplicate_node_occurrences,\n        "duplicate_node_ids": duplicate_node_ids,\n        "unresolved_import_count": len((graph.get("facts") or {}).get("unresolved_imports") or []),\n        "unresolved_import_classes": _classify_unresolved_imports(graph),\n',
    1,
)
text = text.replace(
    '        "integrity_pass": integrity_pass,\n        "undefined_edge_endpoints": missing_endpoints,\n',
    '        "integrity_pass": integrity_pass,\n        "identity_integrity_pass": not duplicate_node_ids,\n        "duplicate_node_ids": duplicate_node_ids,\n        "identity_collision_count": duplicate_node_occurrences,\n        "undefined_edge_endpoints": missing_endpoints,\n',
    1,
)
text = text.replace(
    '        "integrity": {\n            "missing_semantic_edge_evidence": sorted(set(missing_edge_evidence)),\n',
    '        "integrity": {\n            "identity_integrity_pass": not duplicate_node_ids,\n            "duplicate_node_ids": duplicate_node_ids,\n            "identity_collision_count": duplicate_node_occurrences,\n            "missing_semantic_edge_evidence": sorted(set(missing_edge_evidence)),\n',
    1,
)
p.write_text(text)

Path("src/graft_plus/decision.py").write_text('''"""Project reconstruction evidence into independent assurance propositions."""\n\nfrom __future__ import annotations\n\nimport hashlib\nimport json\nfrom typing import Any\n\nfrom graft_plus import GRANTS_EXECUTION_AUTHORITY, IMPLEMENTS_PLAN, MERGE_AUTHORIZATION, PACKAGE, PRODUCT\n\n\ndef _sha(payload: dict[str, Any]) -> str:\n    return hashlib.sha256(json.dumps(payload, sort_keys=True, separators=(",", ":")).encode()).hexdigest()\n\n\ndef _ids(items: list[Any]) -> list[str]:\n    out = []\n    for item in items or []:\n        if isinstance(item, str) and item:\n            out.append(item)\n        elif isinstance(item, dict) and item.get("id"):\n            out.append(str(item["id"]))\n    return sorted(set(out))\n\n\ndef decide(*, graph: dict[str, Any], impact: dict[str, Any], completeness: dict[str, Any]) -> dict[str, Any]:\n    integrity = completeness.get("integrity") or {}\n    residuals = completeness.get("residuals") or {}\n    blocking = list(integrity.get("unacknowledged_blocking_findings") or completeness.get("unacknowledged_blocking_findings") or [])\n    collisions = int(completeness.get("identity_collision_count") or integrity.get("identity_collision_count") or 0)\n    identity_pass = bool(completeness.get("identity_integrity_pass", integrity.get("identity_integrity_pass", not collisions)))\n    artifact_pass = bool(completeness.get("integrity_pass") if "integrity_pass" in completeness else integrity.get("pass"))\n\n    structural_gaps = []\n    for key, reason in (("unmapped_source_file_count", "unmapped_source_files"), ("relationship_unparsed_file_count", "relationship_unparsed_files"), ("unresolved_relationship_boundary_count", "runtime_or_build_context_required"), ("unresolved_import_count", "unresolved_references"), ("stale_graph_source_count", "stale_graph_sources")):\n        if residuals.get(key):\n            structural_gaps.append(reason)\n\n    changed_files = list(impact.get("changed_files") or [])\n    unmapped_changed = list(impact.get("unmapped_changed_files") or [])\n    known_violations = list(integrity.get("known_violations") or [])\n\n    dimensions = {\n        "artifact_integrity": "passed" if artifact_pass else "blocked",\n        "identity_integrity": "passed" if identity_pass else "blocked",\n        "structural_coverage": "gaps-visible" if structural_gaps else "no-known-gaps",\n        "architectural_reconstruction": "bounded" if not structural_gaps and artifact_pass else "incomplete",\n        "change_evidence": "not-requested" if not changed_files else ("partial" if unmapped_changed else "available"),\n        "proof_readiness": "not-established",\n        "execution_authority": "not-granted",\n        "merge_authority": MERGE_AUTHORIZATION,\n    }\n\n    review = list(structural_gaps)\n    if unmapped_changed:\n        review.append("unmapped_changed_files")\n    if known_violations:\n        review.append("known_violations_visible")\n    if not changed_files:\n        review.append("no_git_range")\n    review = sorted(set(review))\n\n    if not artifact_pass or not identity_pass or blocking:\n        disposition = "blocked"\n    elif review:\n        disposition = "review-required"\n    else:\n        disposition = "clear"\n\n    blocking_reasons = list(blocking)\n    if not identity_pass:\n        blocking_reasons.append("canonical_identity_collision")\n    if completeness.get("undefined_edge_endpoints"):\n        blocking_reasons.append("undefined_edge_endpoints")\n    if integrity.get("missing_semantic_edge_evidence"):\n        blocking_reasons.append("missing_semantic_edge_evidence")\n\n    return {\n        "schema_version": "1.2",\n        "product": PRODUCT,\n        "package": PACKAGE,\n        "role": "fact-substrate",\n        "decision": {\n            "architecture_disposition": disposition,\n            "dimensions": dimensions,\n            "merge_authorization": MERGE_AUTHORIZATION,\n            "full_ci_required": True,\n            "blocking_reasons": sorted(set(blocking_reasons)),\n            "review_reasons": review,\n            "warnings": ["unresolved_references_classified"] if residuals.get("unresolved_import_classes") else [],\n        },\n        "grants_execution_authority": GRANTS_EXECUTION_AUTHORITY,\n        "implementsPlan": IMPLEMENTS_PLAN,\n        "completeness": {\n            "integrity_pass": completeness.get("integrity_pass"),\n            "identity_integrity_pass": identity_pass,\n            "identity_collision_count": collisions,\n            "duplicate_node_ids": completeness.get("duplicate_node_ids") or integrity.get("duplicate_node_ids") or [],\n            "undefined_edge_endpoints": completeness.get("undefined_edge_endpoints") or [],\n            "unacknowledged_blocking_findings": blocking,\n            "acknowledged_semantic_findings": completeness.get("acknowledged_findings") or [],\n            "missing_semantic_edge_evidence": integrity.get("missing_semantic_edge_evidence") or [],\n            "semantic_reconciliation_counts": completeness.get("semantic_reconciliation_counts") or {},\n            "unmapped_source_files": residuals.get("unmapped_source_files") or [],\n            "stale_graph_sources": residuals.get("stale_graph_sources") or [],\n            "relationship_unparsed_files": residuals.get("relationship_unparsed_files") or [],\n            "relationship_boundary_count": residuals.get("relationship_boundary_count") or 0,\n            "unresolved_relationship_boundary_count": residuals.get("unresolved_relationship_boundary_count") or 0,\n            "unresolved_import_count": residuals.get("unresolved_import_count") or 0,\n            "unresolved_import_classes": residuals.get("unresolved_import_classes") or {},\n            "evidence_precision_counts": residuals.get("evidence_precision_counts") or {},\n        },\n        "residuals": residuals,\n        "impact": {\n            "changed_files": changed_files,\n            "changed_node_ids": _ids(impact.get("changed_nodes") or []),\n            "unmapped_changed_files": unmapped_changed,\n            "upstream_consumers": _ids(impact.get("upstream_consumers") or []),\n            "downstream_dependencies": _ids(impact.get("downstream_dependencies") or []),\n            "affected_semantic_node_ids": _ids(impact.get("affected_semantic_nodes") or []),\n            "dependency_semantic_node_ids": _ids(impact.get("dependency_semantic_nodes") or []),\n            "impacted_tests": impact.get("impacted_tests") or [],\n            "relevant_invariant_ids": _ids(impact.get("relevant_invariants") or []),\n        },\n        "inputs": {"canonical_graph_sha256": _sha(graph), "metrics": graph.get("metrics") or {}},\n        "negatives": [\n            "This pack is a map. It is not a plan.",\n            "No single disposition substitutes for the independent assurance dimensions.",\n            "merge_authorization is not-determined even when disposition is clear.",\n            "An acknowledgement is not a repair.",\n            "Do not invent missing nodes or unresolved targets.",\n            "Unresolved references are classified residual evidence, not proof of missing files.",\n            "Overlay stays residual until a reviewed relationship is attached.",\n        ],\n    }\n''')

Path("tests/test_machine_native_assurance.py").write_text('''from graft_plus.completeness import audit\nfrom graft_plus.decision import decide\nfrom graft_plus.graph import build_graph\n\n\ndef test_mock_patch_is_not_http_patch_route(tmp_path):\n    pkg = tmp_path / "pkg"\n    pkg.mkdir()\n    (pkg / "__init__.py").write_text("")\n    (pkg / "worker.py").write_text("from unittest import mock\\n@mock.patch('subprocess.run')\\ndef execute(fake_run):\\n    return fake_run\\n")\n    graph = build_graph(subject=tmp_path)\n    assert not any(node["type"] == "http_route" and node.get("method") == "PATCH" for node in graph["nodes"])\n\n\ndef test_duplicate_canonical_identity_blocks_assurance():\n    graph = {"nodes": [{"id": "py:dup", "type": "python_module", "source": "a.py", "layer": "generated"}, {"id": "py:dup", "type": "python_module", "source": "b.py", "layer": "generated"}], "edges": [], "facts": {"unresolved_imports": []}, "metrics": {"node_count": 2, "edge_count": 0, "static_cycles": []}}\n    report = audit(graph)\n    assert report["integrity_pass"] is False\n    assert report["identity_integrity_pass"] is False\n    assert report["identity_collision_count"] == 1\n    decision = decide(graph=graph, impact={"changed_files": []}, completeness=report)\n    assert decision["decision"]["architecture_disposition"] == "blocked"\n    assert decision["decision"]["dimensions"]["identity_integrity"] == "blocked"\n\n\ndef test_unresolved_reference_classes_are_preserved():\n    graph = {"nodes": [{"id": "py:a", "type": "python_module", "source": "a.py", "layer": "generated"}], "edges": [], "facts": {"unresolved_imports": [{"specifier": "chrome:settings", "from": "a.py"}, {"specifier": ".local", "from": "a.py"}, {"specifier": "mystery_pkg", "from": "a.py"}]}, "metrics": {"node_count": 1, "edge_count": 0, "static_cycles": []}}\n    classes = audit(graph)["residuals"]["unresolved_import_classes"]\n    assert classes == {"relative_internal_reference": 1, "unresolved_absolute_reference": 1, "url_or_scheme": 1}\n\n\ndef test_disposition_separates_propositions(tmp_path):\n    (tmp_path / "pkg").mkdir()\n    (tmp_path / "pkg" / "__init__.py").write_text("")\n    (tmp_path / "pkg" / "main.py").write_text("import unknown_package\\n")\n    graph = build_graph(subject=tmp_path)\n    report = audit(graph, subject=tmp_path)\n    decision = decide(graph=graph, impact={"changed_files": []}, completeness=report)\n    dims = decision["decision"]["dimensions"]\n    assert dims["artifact_integrity"] == "passed"\n    assert dims["identity_integrity"] == "passed"\n    assert dims["structural_coverage"] == "gaps-visible"\n    assert dims["change_evidence"] == "not-requested"\n    assert decision["decision"]["architecture_disposition"] == "review-required"\n''')

p = Path("tests/test_reconstruct.py")
text = p.read_text()
text = text.replace('assert decision["decision"]["architecture_disposition"] == "clear"', 'assert decision["decision"]["architecture_disposition"] == "review-required"', 1)
text = text.replace('assert passed["decision"]["architecture_disposition"] == "clear"', 'assert passed["decision"]["architecture_disposition"] == "review-required"', 1)
p.write_text(text)

Path("docs/ASSURANCE.md").write_text("""# G.R.A.F.T.+ assurance model\n\nThe pack separates artifact integrity, canonical identity, structural coverage, architectural reconstruction, change evidence, proof readiness, execution authority, and merge authority. A single scalar disposition is only a compatibility summary and must not substitute for these independent propositions.\n\nThis model is derived from the Chromium stress evidence: ingestion scale, semantic fidelity, identity integrity, coverage, proof, and authority are distinct truths.\n""")
